import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"15 - React UI And Analytics Surfaces","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/15-basic-ui-elements.md","filePath":"developers/design-documentation/15-basic-ui-elements.md"}'),r={name:"developers/design-documentation/15-basic-ui-elements.md"};function i(n,t,c,s,l,h){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="_15-react-ui-and-analytics-surfaces" tabindex="-1">15 - React UI And Analytics Surfaces <a class="header-anchor" href="#_15-react-ui-and-analytics-surfaces" aria-label="Permalink to &quot;15 - React UI And Analytics Surfaces&quot;">​</a></h1><h2 id="application-shell" tabindex="-1">Application Shell <a class="header-anchor" href="#application-shell" aria-label="Permalink to &quot;Application Shell&quot;">​</a></h2><p><code>frontend/src/App.tsx</code> defines public, authenticated, standard-layout, and full-width routes. <code>frontend/src/components/layout/Layout.tsx</code> owns the standard navigation shell; <code>FullWidthLayout.tsx</code> is used for dense workspaces. <code>frontend/src/config/navigation.ts</code> determines visible navigation groups.</p><h2 id="operational-pages" tabindex="-1">Operational Pages <a class="header-anchor" href="#operational-pages" aria-label="Permalink to &quot;Operational Pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Routes/pages</th></tr></thead><tbody><tr><td>Account</td><td>Dashboard, OrderBook, TradeBook, Positions, Holdings</td></tr><tr><td>Automation</td><td>Strategy, Chartink, Python Strategy Host, Flow</td></tr><tr><td>Execution</td><td>Action Center, Analyzer, Sandbox, Scalping</td></tr><tr><td>Monitoring</td><td>PnL Tracker, Latency, Traffic, Health, Security, Logs</td></tr><tr><td>Configuration</td><td>API key, broker credentials, admin, Telegram, WhatsApp</td></tr><tr><td>Data</td><td>Search, Historify, Download, Master Contract</td></tr></tbody></table><p>Account pages combine TanStack Query with Socket.IO-triggered refreshes. The active broker capability store controls exchange/feature options; app mode comes from the backend analyzer setting.</p><h2 id="analytics-and-trading-tools" tabindex="-1">Analytics And Trading Tools <a class="header-anchor" href="#analytics-and-trading-tools" aria-label="Permalink to &quot;Analytics And Trading Tools&quot;">​</a></h2><p>Current routed tools include:</p><table tabindex="0"><thead><tr><th>Route</th><th>Purpose</th><th>Backend source</th></tr></thead><tbody><tr><td><code>/strategybuilder</code></td><td>Multi-leg payoff, Greeks, P&amp;L, strategy chart, OI</td><td>Multiple strategy services</td></tr><tr><td><code>/optionchain</code></td><td>Live option chain and quick execution</td><td><code>option_chain_service.py</code></td></tr><tr><td><code>/ivchart</code></td><td>Historical IV/Greeks charts</td><td><code>iv_chart_service.py</code></td></tr><tr><td><code>/ivsmile</code></td><td>Call/put IV smile and skew</td><td><code>iv_smile_service.py</code></td></tr><tr><td><code>/volsurface</code></td><td>3D volatility surface</td><td><code>vol_surface_service.py</code></td></tr><tr><td><code>/gex</code></td><td>Gamma exposure by strike</td><td><code>gex_service.py</code></td></tr><tr><td><code>/gammadensity</code></td><td>Gamma-times-OI and convexity zones</td><td><code>gamma_density_service.py</code></td></tr><tr><td><code>/oitracker</code></td><td>OI bars and PCR</td><td><code>oi_tracker_service.py</code></td></tr><tr><td><code>/oirange</code></td><td>Client-side strike-range OI view</td><td>Option-chain API</td></tr><tr><td><code>/oiprofile</code></td><td>Candles plus OI profile</td><td><code>oi_profile_service.py</code></td></tr><tr><td><code>/maxpain</code></td><td>Max-pain distribution</td><td>OI tracker max-pain route</td></tr><tr><td><code>/straddle</code></td><td>ATM straddle chart</td><td><code>straddle_chart_service.py</code></td></tr><tr><td><code>/straddlepnl</code></td><td>Custom multi-leg straddle chart</td><td><code>custom_straddle_service.py</code></td></tr><tr><td><code>/arbitrage</code></td><td>Futures calendar-spread scanner</td><td><code>arbitrage_service.py</code></td></tr><tr><td><code>/scalping</code></td><td>Keyboard execution and server-side stop risk</td><td><code>scalping.py</code>, risk monitor</td></tr></tbody></table><p>The tool list is not fixed at twelve; navigation and routes are the current source of truth.</p><h2 id="live-data" tabindex="-1">Live Data <a class="header-anchor" href="#live-data" aria-label="Permalink to &quot;Live Data&quot;">​</a></h2><p>Tools use the shared <code>MarketDataManager</code> through hooks rather than opening ad hoc browser feeds. Continuous option-chain or price views merge initial REST snapshots with WebSocket ticks. Pages use visibility controls and stale-data fallbacks to avoid unnecessary broker traffic.</p><h2 id="shared-components" tabindex="-1">Shared Components <a class="header-anchor" href="#shared-components" aria-label="Permalink to &quot;Shared Components&quot;">​</a></h2><ul><li><code>components/trading/</code>: order dialog, market depth, quote header, GTT and basket execution.</li><li><code>components/strategy-builder/</code>: leg editor, payoff, Greeks, P&amp;L, strategy charts, portfolio save.</li><li><code>components/option-chain/</code>: column configuration and bar settings.</li><li><code>components/scalping/</code>: chart and stop-loss dialog.</li><li><code>components/ui/</code>: local Radix/shadcn-style primitives.</li></ul><h2 id="error-and-loading-behavior" tabindex="-1">Error And Loading Behavior <a class="header-anchor" href="#error-and-loading-behavior" aria-label="Permalink to &quot;Error And Loading Behavior&quot;">​</a></h2><p>TanStack Query owns request states. Route modules are lazy-loaded, <code>ErrorBoundary.tsx</code> handles render failures, <code>PageLoader</code> covers route loading, and Sonner-based helpers in <code>frontend/src/utils/toast.ts</code> expose categorized user feedback.</p><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>frontend/src/App.tsx</code></td><td>Route inventory</td></tr><tr><td><code>frontend/src/config/navigation.ts</code></td><td>Navigation inventory</td></tr><tr><td><code>frontend/src/api/trading.ts</code></td><td>Account/trading client</td></tr><tr><td><code>frontend/src/hooks/useOrderEventRefresh.ts</code></td><td>Event-driven account refresh</td></tr><tr><td><code>frontend/src/lib/MarketDataManager.ts</code></td><td>Shared market-data subscriptions</td></tr><tr><td><code>blueprints/react_app.py</code></td><td>Production SPA route serving</td></tr></tbody></table>',18)])])}const g=e(r,[["render",i]]);export{u as __pageData,g as default};
